-- AGUA MAGALY - endurecimiento, PARTE 2 de 3: saneamiento de pedidos y PQRS.
-- Ejecutar DESPUES de la parte anterior (una sola sentencia).
do $$
begin
execute 'create or replace function public.sanitize_public_record() returns trigger language plpgsql security definer set search_path = public as $fn$ declare d jsonb; n numeric; begin if public.is_staff() then return new; end if; d := coalesce(new.data, ''{}''::jsonb); if new.entity = ''orders'' then d := jsonb_set(d, ''{status}'', to_jsonb(''Pendiente''::text), true); d := jsonb_set(d, ''{driverId}'', ''null''::jsonb, true); d := jsonb_set(d, ''{driverName}'', to_jsonb(''''::text), true); d := jsonb_set(d, ''{paid}'', ''false''::jsonb, true); d := jsonb_set(d, ''{payment}'', to_jsonb(''''::text), true); d := jsonb_set(d, ''{events}'', ''[]''::jsonb, true); d := jsonb_set(d, ''{createdAt}'', to_jsonb(now()), true); d := jsonb_set(d, ''{source}'', to_jsonb(''web''::text), true); begin n := coalesce((d->>''total'')::numeric, 0); exception when others then n := 0; end; n := greatest(0, least(n, 100000000)); d := jsonb_set(d, ''{total}'', to_jsonb(n), true); d := jsonb_set(d, ''{client}'', to_jsonb(left(coalesce(d->>''client'',''''), 120)), true); d := jsonb_set(d, ''{phone}'', to_jsonb(left(coalesce(d->>''phone'',''''), 40)), true); d := jsonb_set(d, ''{address}'', to_jsonb(left(coalesce(d->>''address'',''''), 240)), true); d := jsonb_set(d, ''{items}'', to_jsonb(left(coalesce(d->>''items'',''''), 600)), true); d := jsonb_set(d, ''{notes}'', to_jsonb(left(coalesce(d->>''notes'',''''), 600)), true); elsif new.entity = ''pqrs'' then d := jsonb_set(d, ''{status}'', to_jsonb(''Nueva''::text), true); d := jsonb_set(d, ''{createdAt}'', to_jsonb(now()), true); d := jsonb_set(d, ''{name}'', to_jsonb(left(coalesce(d->>''name'',''''), 120)), true); d := jsonb_set(d, ''{contact}'', to_jsonb(left(coalesce(d->>''contact'',''''), 80)), true); d := jsonb_set(d, ''{message}'', to_jsonb(left(coalesce(d->>''message'',''''), 2000)), true); d := jsonb_set(d, ''{type}'', to_jsonb(left(coalesce(d->>''type'',''Solicitud''), 60)), true); end if; new.data := d; return new; end; $fn$;';
execute 'drop trigger if exists records_sanitize_public on public.records';
execute 'create trigger records_sanitize_public before insert on public.records for each row execute function public.sanitize_public_record()';
end
$$;
